import type { CSSProperties } from 'react';
import { ICON_PATHS } from './icon-paths';

/**
 * Phosphor duotone icon by kebab-case name (the names stored in the database).
 * Unknown names fall back to `chat-circle`.
 *
 * The paths come from `icon-paths.ts`, generated by `npm run icons` from
 * @phosphor-icons/react with only the weights we draw. The library's own
 * components carry all six weights each (#20). The markup matches theirs.
 * `fill` exists only for the icons listed in FILL in scripts/gen-icons.mjs;
 * other icons draw duotone instead.
 */
export function Icon({
  name,
  size = 18,
  color = 'currentColor',
  style,
  weight = 'duotone',
  className,
}: {
  name: string;
  size?: number;
  color?: string;
  style?: CSSProperties;
  weight?: 'duotone' | 'fill';
  className?: string;
}) {
  const icon = ICON_PATHS[name] ?? ICON_PATHS['chat-circle'];
  const paths = (weight === 'fill' && icon.fill) || icon.duotone;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      fill={color}
      viewBox="0 0 256 256"
      style={{ flex: 'none', ...style }}
      className={className}
      aria-hidden
    >
      {paths.map((p, i) => (typeof p === 'string' ? <path key={i} d={p} /> : <path key={i} d={p[0]} opacity={p[1]} />))}
    </svg>
  );
}
